import sys
from collections import deque

def main():
    data = sys.stdin.buffer.read().split()
    idx = 0
    H = int(data[idx]); idx += 1
    W = int(data[idx]); idx += 1
    grid = []
    for _ in range(H):
        grid.append(data[idx].decode()); idx += 1
    A = int(data[idx]) - 1; idx += 1
    B = int(data[idx]) - 1; idx += 1
    C = int(data[idx]) - 1; idx += 1
    D = int(data[idx]) - 1; idx += 1

    INF = 10**9
    N = H * W
    dist = [INF] * N
    seen = [False] * N
    s = A * W + B
    t = C * W + D
    dist[s] = 0
    dq = deque([s])

    while dq:
        p = dq.popleft()
        if seen[p]:
            continue
        seen[p] = True
        if p == t:
            break
        r, c = divmod(p, W)
        d = dist[p]
        nd = d + 1
        # 0-weight: adjacent road cells
        if r > 0:
            np = p - W
            if not seen[np] and grid[r-1][c] == '.' and dist[np] > d:
                dist[np] = d
                dq.appendleft(np)
        if r < H - 1:
            np = p + W
            if not seen[np] and grid[r+1][c] == '.' and dist[np] > d:
                dist[np] = d
                dq.appendleft(np)
        if c > 0:
            np = p - 1
            if not seen[np] and grid[r][c-1] == '.' and dist[np] > d:
                dist[np] = d
                dq.appendleft(np)
        if c < W - 1:
            np = p + 1
            if not seen[np] and grid[r][c+1] == '.' and dist[np] > d:
                dist[np] = d
                dq.appendleft(np)
        # 1-weight: kick up to 2 cells in any cardinal direction
        if r > 0:
            np = p - W
            if not seen[np] and dist[np] > nd:
                dist[np] = nd
                dq.append(np)
        if r > 1:
            np = p - 2 * W
            if not seen[np] and dist[np] > nd:
                dist[np] = nd
                dq.append(np)
        if r < H - 1:
            np = p + W
            if not seen[np] and dist[np] > nd:
                dist[np] = nd
                dq.append(np)
        if r < H - 2:
            np = p + 2 * W
            if not seen[np] and dist[np] > nd:
                dist[np] = nd
                dq.append(np)
        if c > 0:
            np = p - 1
            if not seen[np] and dist[np] > nd:
                dist[np] = nd
                dq.append(np)
        if c > 1:
            np = p - 2
            if not seen[np] and dist[np] > nd:
                dist[np] = nd
                dq.append(np)
        if c < W - 1:
            np = p + 1
            if not seen[np] and dist[np] > nd:
                dist[np] = nd
                dq.append(np)
        if c < W - 2:
            np = p + 2
            if not seen[np] and dist[np] > nd:
                dist[np] = nd
                dq.append(np)

    print(dist[t])

main()

